/bin/bash -lc "python - <<'PY'
import pathlib,re,subprocess
patterns={'aws-id':r'(?:AKIA|ASIA)[A-Z0-9]{16}','github':r'(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{30,})','huggingface':r'hf_[A-Za-z0-9]{20,}','other-token':r'(?:sk-[A-Za-z0-9_-]{20,}|AIza[A-Za-z0-9_-]{30,})'}
for p in pathlib.Path('.').rglob('*'):
 if '.git' in p.parts or not p.is_file():continue
 try:s=p.read_text()
 except (UnicodeError,OSError):continue
 for n,l in enumerate(s.splitlines(),1):
  hits=[k for k,v in patterns.items() if re.search(v,l)]
  if hits:print(str(p),n,','.join(hits))
  elif re.search(r'(?i)(secret|token|api.?key|access.?key|password|credential)',l):
   # show only variable names and masked value to avoid exposing credentials
   print(str(p),n,'CANDIDATE',re.sub(r'([:=]).*',r'\\1 [REDACTED]',l.strip())[:150])
print('COMMITS',subprocess.check_output(['git','rev-list','--all','--count'],text=True).strip())
PY"

