import pathlib,re,math,collections,ast,json,subprocess
pattern=re.compile(r'(?:AKIA|ASIA)[A-Z0-9]{16}|(?:gh[pousr]_|github_pat_|hf_)[A-Za-z0-9_]{20,}|sk-[A-Za-z0-9_-]{20,}|AIza[A-Za-z0-9_-]{30,}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----')
hits=[]; candidates=[]
for p in pathlib.Path('.').rglob('*'):
 if '.git' in p.parts or not p.is_file():continue
 try:s=p.read_text()
 except (UnicodeError,OSError):continue
 for n,l in enumerate(s.splitlines(),1):
  if pattern.search(l):hits.append((str(p),n))
  for m in re.finditer(r'''[\"']([A-Za-z0-9_+/=-]{32,100})[\"']''',l):
   v=m.group(1); counts=collections.Counter(v); entropy=-sum(c/len(v)*math.log2(c/len(v)) for c in counts.values())
   if entropy>4.3 and not re.fullmatch('[0-9a-fA-F]+',v):candidates.append((str(p),n,len(v)))
print('REMAINING CREDENTIAL PATTERN MATCHES',hits)
print('HIGH ENTROPY LITERAL CANDIDATES',candidates)
ast.parse(pathlib.Path('ray_processing/process.py').read_text())
json.loads(pathlib.Path('exp_data/datasets/tokenized/rw_v2_fasttext_openhermes_vs_rw_v2_bigram_0.1_arcade100k.json').read_text())
try:
 import yaml
 yaml.safe_load(pathlib.Path('ray_processing/ray_cluster.yaml').read_text())
 print('Python, JSON, YAML syntax checks passed')
except ImportError:print('Python and JSON syntax checks passed; YAML parser unavailable')
# Show additions only, to keep removed credentials out of tool output.
diff=subprocess.check_output(['git','diff','--unified=0'],text=True)
for l in diff.splitlines():
 if l.startswith(('+++','@@')) or (l.startswith('+') and not l.startswith('+++')):
  print(l[:500])
