/bin/bash -lc "python - <<'PY'
import pathlib,re,math,collections,subprocess
contexts=collections.Counter()
for p in pathlib.Path('.').rglob('*'):
 if '.git' in p.parts or not p.is_file():continue
 try:s=p.read_text()
 except (UnicodeError,OSError):continue
 for l in s.splitlines():
  for m in re.finditer(r'''[\"']([A-Za-z0-9_+/=-]{32,100})[\"']''',l):
   v=m.group(1);c=collections.Counter(v);h=-sum(n/len(v)*math.log2(n/len(v)) for n in c.values())
   if h>4.3 and not re.fullmatch('[0-9a-fA-F]+',v):
    if p.suffix=='.html':
     attr=re.search(r'([\\w:-]+)\\s*=\\s*"'$'"',l[:m.start()]); key=attr.group(1) if attr else 'HTML content'
    else:
     key=re.findall(r'\"(["'^"'"\\n]+)\"\\s*:',l[:m.start()]);key=key[-1] if key else 'non-key literal'
    contexts[(p.suffix,key)]+=1
print('Entropy candidate contexts:',dict(contexts))
changed=subprocess.check_output(['git','diff','--name-only'],text=True).splitlines()
patterns=[(r'(?:AKIA|ASIA)[A-Z0-9]{16}','<your-aws-access-key-id>'),(r'gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{30,}','<your-github-token>'),(r'hf_[A-Za-z0-9]{20,}','<your-huggingface-token>')]
for path in changed:
 old=subprocess.check_output(['git','show','HEAD:'+path]).decode()
 for pat,val in patterns:old=re.sub(pat,lambda m:val,old)
 old=re.sub(r'(AWS_SECRET_ACCESS_KEY[\\\"\\x27]?\\]?\\s*=\\s*[\\\"\\x27]?)([A-Za-z0-9/+=]{40})(?"'![A-Za-z0-9/+=])'"',lambda m:m.group(1)+'<your-aws-secret-access-key>',old)
 assert old==pathlib.Path(path).read_text(),path
print('Verified every edit is a credential-to-placeholder replacement in exactly three files.')
PY"

